"""csv-stats CLI entry point.

Reads a CSV file (or stdin) and prints aggregate statistics
(sum, mean, max, min) for numeric columns in a table format on stdout.
Standard library only.
"""
from __future__ import annotations

import argparse
import csv
import sys
from typing import Dict, List, Optional


def build_parser() -> argparse.ArgumentParser:
    """Build the argparse parser for the csv-stats CLI."""
    parser = argparse.ArgumentParser(
        prog="csv-stats",
        description=(
            "Read a CSV file and print sum, mean, max, and min "
            "for numeric columns as a table."
        ),
    )
    parser.add_argument(
        "csv_file",
        nargs="?",
        default=None,
        help="Path to the CSV file. If omitted, CSV data is read from stdin.",
    )
    parser.add_argument(
        "--delimiter",
        default=",",
        help="Field delimiter used in the CSV data (default: ',').",
    )
    return parser


def parse_number(value: str) -> Optional[float]:
    """Return the value as a float, or None if it is not numeric."""
    text = value.strip()
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        return None


def collect_numeric_columns(
    header: List[str], rows: List[List[str]]
) -> Dict[str, List[float]]:
    """Map each numeric column name to its list of float values.

    A column is considered numeric if it contains at least one numeric
    value and no non-blank, non-numeric values.
    """
    values: Dict[str, List[float]] = {}
    numeric_ok: Dict[str, bool] = {}

    for name in header:
        values[name] = []
        numeric_ok[name] = True

    for row in rows:
        for i, name in enumerate(header):
            if i >= len(row):
                continue
            cell = row[i]
            if not cell.strip():
                continue
            number = parse_number(cell)
            if number is None:
                numeric_ok[name] = False
            else:
                values[name].append(number)

    return {
        name: vals
        for name, vals in values.items()
        if numeric_ok.get(name) and vals
    }


def format_number(value: float) -> str:
    """Format a float, dropping a trailing '.0' for whole numbers."""
    if value == int(value) and abs(value) < 1e16:
        return str(int(value))
    return f"{value:.6g}"


def render_table(
    column_names: List[str], stats: Dict[str, Dict[str, float]]
) -> str:
    """Render the statistics as a fixed-width text table."""
    metric_names = ["sum", "mean", "max", "min"]
    row_labels = [name + " " for name in column_names]

    # Build a grid: first header row is metric names, then one row per CSV column.
    header_cells = ["column"] + metric_names
    grid: List[List[str]] = [header_cells]
    for name in column_names:
        row = [name] + [format_number(stats[name][m]) for m in metric_names]
        grid.append(row)

    widths = [0] * len(header_cells)
    for row in grid:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    def fmt_row(cells: List[str]) -> str:
        return "  ".join(cell.ljust(widths[i]) for i, cell in enumerate(cells)).rstrip()

    lines = [fmt_row(grid[0]), "  ".join("-" * w for w in widths)]
    for row in grid[1:]:
        lines.append(fmt_row(row))
    return "\n".join(lines)


def compute_stats(numeric: Dict[str, List[float]]) -> Dict[str, Dict[str, float]]:
    """Compute sum, mean, max, min for each numeric column."""
    stats: Dict[str, Dict[str, float]] = {}
    for name, vals in numeric.items():
        stats[name] = {
            "sum": sum(vals),
            "mean": sum(vals) / len(vals),
            "max": max(vals),
            "min": min(vals),
        }
    return stats


def read_rows(text: str, delimiter: str):
    """Parse CSV text into (header, rows)."""
    reader = csv.reader(text.splitlines(), delimiter=delimiter)
    rows = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not rows:
        return None, []
    return rows[0], rows[1:]


def run(csv_file: Optional[str], delimiter: str) -> int:
    """Read CSV data and print the numeric-column statistics table."""
    if csv_file is None or csv_file == "-":
        if sys.stdin.isatty():
            print(
                "csv-stats: no CSV file given and stdin is a terminal.\n"
                "Usage: csv-stats [OPTIONS] [CSV_FILE]\n"
                "Try 'csv-stats --help' for help.",
                file=sys.stderr,
            )
            return 2
        text = sys.stdin.read()
    else:
        try:
            with open(csv_file, newline="", encoding="utf-8-sig") as fh:
                text = fh.read()
        except OSError as exc:
            print(f"csv-stats: cannot read {csv_file!r}: {exc}", file=sys.stderr)
            return 1

    header, rows = read_rows(text, delimiter)
    if header is None:
        print("csv-stats: no CSV data found.", file=sys.stderr)
        return 1

    numeric = collect_numeric_columns(header, rows)
    if not numeric:
        print("csv-stats: no numeric columns found.", file=sys.stderr)
        return 1

    # Preserve original column order from the header.
    ordered = [name for name in header if name in numeric]
    stats = compute_stats(numeric)
    print(render_table(ordered, stats))
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entry point for csv-stats."""
    parser = build_parser()
    args = parser.parse_args(argv)
    return run(args.csv_file, args.delimiter)


if __name__ == "__main__":
    sys.exit(main())
